<template>
 <div class="ai-ops">
  <header class="ops-header"><div><h1>{{ $t('aiOperations.title') }}</h1><p>{{ $t('aiOperations.providerNote') }}</p></div><div class="ops-actions"><label><input v-model="autoRefresh" type="checkbox" :disabled="!authorized || forbidden" /> {{ $t('aiOperations.auto') }}</label><button type="button" :disabled="!authorized || forbidden || loading" @click="refresh">{{ $t('aiOperations.refresh') }}</button></div></header>
  <p v-if="!authorized || forbidden" class="notice" role="alert">{{ $t('aiOperations.forbidden') }}</p>
  <template v-else>
   <p v-if="error" class="notice" role="alert">{{ $t('aiOperations.unavailable') }} <button type="button" @click="refresh">{{ $t('aiOperations.retry') }}</button></p>
   <p v-if="loading && !snapshot" class="status" role="status">{{ $t('aiOperations.connection') }}</p>
   <template v-if="snapshot">
    <div class="ops-meta"><span>{{ $t('aiOperations.observed') }}: {{ date(snapshot.generated_at) }}</span><span>{{ $t('aiOperations.status') }}: {{ stateLabel(snapshot.state) }}</span></div>
    <section class="panel"><h2>{{ $t('aiOperations.overview') }}</h2><div class="table-wrap"><table><thead><tr><th>{{ $t('aiOperations.categories') }}</th><th>{{ $t('aiOperations.status') }}</th><th>{{ $t('aiOperations.active') }}</th><th>{{ $t('aiOperations.queued') }}</th><th>{{ $t('aiOperations.completed') }} · {{ $t('aiOperations.recent') }}</th><th>{{ $t('aiOperations.failed') }} · {{ $t('aiOperations.recent') }}</th><th>{{ $t('aiOperations.canceledRecent') }}</th><th>{{ $t('aiOperations.expired') }}</th><th>{{ $t('aiOperations.overdue') }}</th><th>{{ $t('aiOperations.lastSuccess') }}</th></tr></thead><tbody><tr v-for="flow in flows" :key="flow.id"><th>{{ $t(flow.label) }}</th><td>{{ stateLabel(flow.data?.state) }}</td><td>{{ flowValue(flow.data,'active') }}</td><td>{{ flowValue(flow.data,'queued') }}</td><td>{{ outcome(flow.data,'completed') }}</td><td>{{ outcome(flow.data,'failed') }}</td><td>{{ outcome(flow.data,'canceled') }}</td><td>{{ flowValue(flow.data,'expired_leases') }}</td><td>{{ flowValue(flow.data,'queue_overdue') }}</td><td>{{ flow.data?.state === 'ok' ? date(flow.data.observed_last_success_at) : unknown(flow.data?.state) }}</td></tr></tbody></table></div></section>
    <div class="ops-grid"><section class="panel"><h2>{{ $t('aiOperations.alerts') }}</h2><ul v-if="alerts.length" class="alert-list"><li v-for="(alert,index) in alerts" :key="index"><span class="warning-dot" />{{ $t(alert.label) }} · {{ $t(flowLabels[alert.flow]) }} <strong>{{ count(alert.count) }}</strong></li></ul><p v-else class="muted">{{ $t('aiOperations.noKnownAlerts') }}</p></section>
     <section class="panel"><h2>{{ $t('aiOperations.budget') }}</h2><template v-if="runtime?.state === 'ok' && runtime.snapshot"><div v-if="runtime.snapshot.service_limited" class="limit-warning">{{ $t('aiOperations.serviceLimit') }}</div><div class="budget-values"><div><small>{{ $t('aiOperations.serviceActive') }}</small><strong>{{ count(runtime.snapshot.service?.active) }} <span>/ {{ count(runtime.snapshot.limits?.service_max_active) }}</span></strong></div><div><small>{{ $t('aiOperations.serviceRequests') }} · {{ $t('aiOperations.recent') }}</small><strong>{{ count(runtime.snapshot.service?.hourly_requests) }} <span>/ {{ count(runtime.snapshot.limits?.service_hourly_requests) }}</span></strong></div></div><p class="muted">{{ $t('aiOperations.adminUsage') }} · {{ $t('aiOperations.adminUsageNote') }} · {{ $t('aiOperations.lowerBound') }}</p><p>{{ $t('aiOperations.knownTokens') }}: {{ count(runtime.snapshot.usage?.known_tokens) }} · {{ $t('aiOperations.unknownReports') }}: {{ count(runtime.snapshot.usage?.unknown_token_reports) }}</p><p>{{ $t('aiOperations.knownCharacters') }}: {{ count(runtime.snapshot.usage?.known_speech_characters) }} · {{ $t('aiOperations.unknownReports') }}: {{ count(runtime.snapshot.usage?.unknown_speech_reports) }}</p></template><p v-else class="muted">{{ unknown(runtime?.state) }}</p></section></div>
    <section class="panel"><h2>{{ $t('aiOperations.failed') }} · {{ $t('aiOperations.recent') }}</h2><div class="failure-grid"><div v-for="flow in flows" :key="flow.id"><strong>{{ $t(flow.label) }}</strong><p v-if="flow.data?.state !== 'ok'" class="muted">{{ unknown(flow.data?.state) }}</p><p v-else-if="!groups(flow.data).length" class="muted">—</p><p v-for="group in groups(flow.data)" :key="group.group">{{ $t(groupLabels[group.group]) }} <b>{{ count(group.count) }}</b></p></div></div></section>
   </template>
  </template>
 </div>
</template>
<script>
import {useAuthStore} from '../stores/auth';
import {isSupportAdmin} from '../utils/support.mjs';
import diagnostics from '../apis/module/diagnostics';
const flowLabels={ai:'aiOperations.flowAi',realtime:'aiOperations.flowRealtime',material:'aiOperations.flowMaterial',speech:'aiOperations.flowSpeech'};
const groupLabels={provider:'aiOperations.groupProvider',authorization:'aiOperations.groupAuthorization',cancellation:'aiOperations.groupCancellation',timeout:'aiOperations.groupTimeout',limits:'aiOperations.groupLimits',media:'aiOperations.groupMedia',configuration:'aiOperations.groupConfiguration',other:'aiOperations.groupOther'};
const alertLabels={LEASE_OVERDUE:'aiOperations.alertLease',QUEUE_OVERDUE:'aiOperations.alertQueue',PROVIDER_FAILURE_CONCENTRATION:'aiOperations.alertProvider'};
export default {name:'AiOperations',setup(){return {auth:useAuthStore()};},data:()=>({snapshot:null,loading:false,error:false,forbidden:false,autoRefresh:false,timer:null,controller:null,epoch:0,flowLabels,groupLabels}),computed:{authorized(){return !!this.auth.bearer&&!/^xext_/i.test(this.auth.bearer)&&isSupportAdmin(this.auth.userInfo);},identity(){return JSON.stringify([this.auth.bearer,this.auth.userInfo?.superAdmin,this.auth.userInfo?.id,this.auth.userInfo?.user_id]);},flows(){return Object.entries(flowLabels).map(([id,label])=>({id,label,data:this.snapshot?.flows?.[id]}));},runtime(){return this.snapshot?.runtime_control;},alerts(){return Array.isArray(this.snapshot?.alerts)?this.snapshot.alerts.filter(x=>alertLabels[x.code]&&flowLabels[x.flow]&&x.severity==='warning').map(x=>({...x,label:alertLabels[x.code]})):[];}},watch:{identity:{flush:'sync',handler(){this.reset();}},autoRefresh(value){clearInterval(this.timer);this.timer=value?setInterval(()=>{if(!document.hidden)this.refresh();},15000):null;}},mounted(){this.reset();},beforeUnmount(){this.epoch++;this.controller?.abort();clearInterval(this.timer);},methods:{
 count(value){return typeof value==='string'&&/^\d+$/.test(value)?value:typeof value==='number'&&Number.isSafeInteger(value)&&value>=0?String(value):this.$t('aiOperations.unknown');},unknown(state){return this.$t(state==='disabled'?'aiOperations.disabled':'aiOperations.unknown');},stateLabel(state){return this.$t(state==='ok'?'aiOperations.ledgerReadable':state==='limited'?'aiOperations.limited':state==='degraded'?'aiOperations.degraded':state==='disabled'?'aiOperations.disabled':'aiOperations.unknown');},date(value){const n=typeof value==='string'?Date.parse(value):NaN;return Number.isFinite(n)?new Date(n).toLocaleString():this.$t('aiOperations.unknown');},flowValue(flow,key){return flow?.state==='ok'?this.count(flow[key]):this.unknown(flow?.state);},outcome(flow,key){return flow?.state==='ok'?this.count(flow.outcomes_60m?.[key]):this.unknown(flow?.state);},groups(flow){return Array.isArray(flow.error_groups_60m)?flow.error_groups_60m.filter(x=>groupLabels[x.group]&&/^\d+$/.test(String(x.count))):[];},
 reset(){this.epoch++;this.controller?.abort();clearInterval(this.timer);this.timer=null;this.autoRefresh=false;this.snapshot=null;this.error=false;this.forbidden=false;this.loading=false;if(this.authorized)this.refresh();},
 async refresh(){if(!this.authorized)return;this.controller?.abort();const version=++this.epoch,controller=new AbortController();this.controller=controller;this.loading=true;this.error=false;try{const result=await diagnostics.read(controller.signal);if(version!==this.epoch||controller.signal.aborted||!this.authorized)return;if(!result||!['limited','degraded'].includes(result.state)||typeof result.flows!=='object'||!Array.isArray(result.alerts))throw new Error('INVALID_DIAGNOSTICS');this.snapshot=result;this.forbidden=false;}catch(e){if(version!==this.epoch||controller.signal.aborted)return;this.snapshot=null;if(e.status===403){this.forbidden=true;this.autoRefresh=false;clearInterval(this.timer);this.timer=null;}else this.error=true;}finally{if(version===this.epoch)this.loading=false;}}
 }};
</script>
<style scoped>
.ai-ops{width:100%;margin:0;padding:0;color:var(--admin-text)}.ops-header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:20px}.ops-header h1{font-size:var(--admin-font-title);margin:0 0 8px}.ops-header p,.muted{color:var(--el-text-color-secondary);font-size:var(--admin-font-base);margin:0}.ops-actions{display:flex;align-items:center;gap:16px;white-space:nowrap;font-size:var(--admin-font-base)}.ops-actions button,.notice button{border:0;border-radius:6px;background:var(--el-color-primary);color:white;padding:8px 15px;cursor:pointer}.ops-actions button:disabled{opacity:.5}.ops-meta{display:flex;gap:20px;color:var(--el-text-color-secondary);font-size:var(--admin-font-xs);margin:0 0 14px}.panel{background:var(--el-bg-color);border:1px solid var(--admin-border);border-radius:10px;padding:18px;margin-bottom:16px;box-shadow:var(--el-box-shadow-lighter)}.panel h2{font-size:var(--admin-font-md);margin:0 0 15px}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:var(--admin-font-base);text-align:left;white-space:nowrap}th,td{padding:12px 10px;border-bottom:1px solid var(--el-border-color-lighter)}thead{color:var(--el-text-color-secondary)}tbody th{color:var(--admin-text)}.ops-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.alert-list{list-style:none;padding:0;margin:0}.alert-list li{padding:8px 0;font-size:var(--admin-font-base)}.alert-list strong{float:right}.warning-dot{display:inline-block;width:7px;height:7px;background:var(--el-color-warning);border-radius:50%;margin-right:9px}.budget-values{display:flex;gap:40px;margin-bottom:16px}.budget-values small{display:block;color:var(--el-text-color-secondary)}.budget-values strong{font-size:var(--admin-font-title)}.budget-values strong span{font-size:var(--admin-font-base);font-weight:400;color:var(--el-text-color-placeholder)}.panel p{font-size:var(--admin-font-base)}.failure-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;font-size:var(--admin-font-base)}.failure-grid p b{float:right}.notice{padding:12px 15px;background:var(--el-color-warning-light-9);border-radius:8px;color:var(--el-color-warning-dark-2)}.limit-warning{color:var(--el-color-warning-dark-2);font-size:var(--admin-font-base);margin-bottom:10px}@media(max-width:760px){.ops-header{flex-direction:column}.ops-grid{grid-template-columns:1fr}.failure-grid{grid-template-columns:repeat(2,1fr)}}
</style>
